from pathlib import Path
import re
R=Path(__file__).resolve().parents[1]
def rd(p): return (R/p).read_text(encoding='utf-8')
def wr(p,s):
 q=R/p;q.parent.mkdir(parents=True,exist_ok=True);q.write_text(s,encoding='utf-8')
def rep(p,a,b,n=1):
 s=rd(p)
 if s.count(a)<n: raise RuntimeError(f'{p}: missing anchor {a[:80]!r}')
 wr(p,s.replace(a,b,n))
def sub(p,a,b,n=1):
 s,c=re.subn(a,b,rd(p),count=n,flags=re.S)
 if c!=n: raise RuntimeError(f'{p}: regex {c}/{n} {a[:80]!r}')
 wr(p,s)

